ALTER TABLE users ADD COLUMN IF NOT EXISTS FailedLoginAttempts INT UNSIGNED NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS LoginLockedUntil DATETIME NULL;
CREATE TABLE IF NOT EXISTS auth_rate_limits (BucketHash CHAR(64) PRIMARY KEY, Attempts INT UNSIGNED NOT NULL DEFAULT 0, ExpiresAt BIGINT NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS password_reset_requests (RequestHash CHAR(64) PRIMARY KEY, UserID INT NULL, Email VARCHAR(100) NOT NULL, CodeHash VARCHAR(255) NOT NULL, ExpiresAt BIGINT NOT NULL, Attempts INT UNSIGNED NOT NULL DEFAULT 0, Verified TINYINT NOT NULL DEFAULT 0, Consumed TINYINT NOT NULL DEFAULT 0, INDEX(UserID)) ENGINE=InnoDB;
